answer_code:
attempts = {"count": 0}

def fetch():
    attempts["count"] += 1
    if attempts["count"] < 3:
        raise RuntimeError("暂时失败")
    return "成功"

def always_fail():
    raise RuntimeError("一直失败")

def retry(func, times):
    for _ in range(times):
        try:
            return func()
        except RuntimeError:
            continue
    return "重试失败"

print(retry(fetch, 3))
print(retry(always_fail, 3))
